from checkpoint import *
A='atiyahhitchinsinger1977deformations'; W='atiyahward1977instantons'; M='drinfeldmanin1978selfdual'; U='uhlenbeck1982removable'; P='dayapremawaldron2026parabolic'
begin(432)
item(432,'P000730','definition','Connections, curvature and local pure gauges',r'The connection form \(A=A_\mu dx^\mu\), curvature \(dA+[A,A]\), gauge transformation and the flat-connection form are introduced; chiral fields are mentioned.',r'For a compact matrix group, \(F_A=dA+A\wedge A\), or \(dA+\frac12[A\wedge A]\) when the bracket notation includes both antisymmetrized terms. A smooth flat connection is locally gauge-equivalent to the trivial connection, and globally so on a simply connected domain. A group-valued field produces a flat Maurer--Cartan form; a chiral field equation imposes additional conditions.',r'This is background to the gauge-theoretic constructions of \citet[\S1]{'+M+r'} and the definitions in \citet[\S2.1]{'+P+r'}. The earlier occurrence 1975-386.1 treats Yang--Mills connections and action.',[M,P],area='Gauge theory',cls='E')
item(432,'P000730','definition','Topological charge requires a trace and normalization',r'The integral of \(\varepsilon_{abcd}F^{ab}F^{cd}\) is said to be an integer up to a factor, without a written trace.',r'For an \(\operatorname{SU}(2)\)-connection extending over \(S^4\), use anti-Hermitian matrices in the defining representation and define \(k=-(8\pi^2)^{-1}\int_{S^4}\operatorname{tr}(F\wedge F)\in\mathbb Z\), with the sign of the integer fixed by orientation. A matrix-valued integral without the invariant trace is not a characteristic number.',r'\citet[\S2.4]{'+P+r'} state a precise characteristic-number convention. The notebook\textquotesingle s coefficient cannot be compared without fixing the trace and component normalization.',[P],area='Gauge theory',cls='E',literal='false as written',match='partial',development='annotated')
item(432,'P000730','definition','Yang–Mills variation and the abelian case',r'The action is the integral of \(\operatorname{Sp}(F_{\mu\nu}F^{\mu\nu})\), and the equation is \(\delta S=0\). Electrodynamics is assigned \(SU(1)\) or \(\mathbb R\).',r'With a positive invariant inner product on the Lie algebra, the action is a positive multiple of \(\int|F_A|^2\), and its Euler--Lagrange equation is \(d_A^*F_A=0\). The compact abelian gauge group is \(U(1)\), whose Lie algebra is one-dimensional; \(SU(1)\) is trivial.',r'\citet[\S1]{'+P+r'} state the action and equation. The \(SU(1)\) reading is visible on P000730 and is a faithful notebook error.',[P],area='Gauge theory',cls='E',literal='false as written',match='partial')
item(432,'P000730','problem','Classifying all finite-action Yang–Mills critical points',r'The classical problem is to find all \(A\) satisfying the Yang--Mills equations and \(S(A)<\infty\).',r'Classify, modulo smooth gauge transformations and with a fixed compact gauge group, smooth Yang--Mills connections on \(\mathbb R^4\) of finite \(L^2\)-curvature. After removable-singularity compactification this is the classification of Yang--Mills critical connections on bundles over the round \(S^4\), not merely their self-dual minima.',r'The instanton part is explicitly classified by \citet[Theorem in \S4]{'+M+r'}. Nonminimal critical points exist, and \citet[\S1, Theorem~1.1]{'+P+r'} distinguish them from instantons and prove a low-energy deformation theorem. These results do not classify all finite-action critical points.',[M,P,U],area='Gauge theory',cls='C',problem='GP-1977-23',worth='A bounded energy or symmetry-restricted version is worth studying, because the full critical-point classification extends far beyond the instanton construction.',match='partial',confidence='medium',status='As of 10 November 2026, the instanton classification and substantial energy-gap results are established; the sources checked do not provide a full classification of all nonminimal Yang--Mills critical connections.')
item(432,'P000730','claim','Finite action and extension over the point at infinity',r'Requiring a field on \(S^4\) is called slightly stronger than finite energy on \(\mathbb R^4\).',r'For a smooth Yang--Mills connection with compact structure group in dimension four, finite \(\int|F_A|^2\) implies smooth extension, after a gauge change, across the point at infinity on a suitable bundle over \(S^4\). For an arbitrary connection not satisfying Yang--Mills, the same conclusion is not supplied by this theorem.',r'\citet[abstract and main removable-singularity result]{'+U+r'} establish the equivalence for Yang--Mills fields. The result was announced in 1979 and fully published in 1982; the publisher page verifies both the result and the earlier announcement citation, although the full original proof was not accessible here.',[U],area='Gauge theory',cls='B',literal='correct with missing hypotheses',verification='publisher metadata checked',match='exact')
item(432,'P000730-P000731','theorem','Four-dimensional conformal invariance',r'The Euclidean metric and round sphere are conformally equivalent; the conformal group is written \(O(5,1)\), with a light-cone construction.',r'In four dimensions the Hodge star on two-forms and the Yang--Mills action are conformally invariant. The conformal group of the round sphere is \(O(5,1)/\{\pm I\}\), with appropriate components for orientation preservation; \(S^4\) is the projectivized null cone in \(\mathbb R^{5,1}\). Pullback by smooth conformal diffeomorphisms preserves the equations. An arbitrary continuous map need not do so.',r'Conformal geometry is part of the construction in \citet{'+W+r'}; \citet[\S1]{'+M+r'} explicitly fix the standard conformal structure on \(S^4\).',[W,M],area='Gauge theory',cls='E',literal='false as written',match='partial',verification='indirect')
item(432,'P000731','theorem','The topological energy bound and self-dual minima',r'The notes state \(S\geq n\), with a strict minimum at a self-dual field.',r'With action \(E=-\int\operatorname{tr}(F\wedge *F)\) and charge as above, \(E\geq8\pi^2|k|\); equality holds exactly for one of \(F=\pm *F\), with sign chosen according to \(k\). The minimum is not strict along a nontrivial instanton moduli space or along gauge orbits.',r'\citet[\S1 and \S2.4]{'+P+r'} state the minimizing role of instantons in a fixed bundle. The notebook suppresses the absolute value and normalization and overstates strictness.',[P],area='Gauge theory',cls='E',literal='false as written',match='partial',development='annotated')
item(432,'P000731','construction','Multi-instanton ansätze and the all-charge problem',r'The notes attribute a \(5n+4\)-parameter family to \textquotesingle t Hooft, state completeness for charge two, and contrast it with dimension \(8n-3\).',r'Explicit multi-instanton ansätze yield finite-dimensional subfamilies at each positive charge. Their raw parameter counts must be reduced by redundancies and gauge conventions: \(5n+4\) is not simultaneously a count of independent unframed moduli at \(n=2\), where \(8n-3=13\). Complete classification requires the more general linear algebra construction.',r'\citet[\S4]{'+M+r'} subsequently give all instantons for the classical compact groups. The source\textquotesingle s numerical attribution and redundancy count are not certified by that theorem, and are recorded as a partial historical match rather than silently corrected to a named ansatz.',[M,A],area='Gauge theory',cls='B',literal='false as written',match='partial',confidence='medium',problem='GP-1977-24')
item(432,'P000731-P000732','theorem','Dimension of the SU2 instanton moduli space',r'The dimension is \(8n-3\); an index calculation and removal of three gauge parameters are described.',r'For charge \(k\geq1\) and the round metric on \(S^4\), the moduli space of irreducible \(SU(2)\) anti-self-dual connections modulo the full gauge group is smooth of real dimension \(8k-3\). The framed moduli space has dimension \(8k\). At charge zero the trivial connection has a nontrivial stabilizer and the same formula does not apply.',r'\citet[pp.2662--2663]{'+A+r'} published the result in July 1977, before this talk; the exact dimension is independently stated in the publisher-hosted abstract.',[A],area='Gauge theory',cls='E',literal='correct with missing hypotheses',verification='publisher metadata checked')
item(432,'P000732','method','The elliptic deformation complex and obstruction vanishing',r'The duality equation is linearized; the cokernel is said to vanish by Hodge-theoretic considerations.',r'For an anti-self-dual connection the deformation complex is \(\Omega^0(\operatorname{ad}E)\xrightarrow{d_A}\Omega^1(\operatorname{ad}E)\xrightarrow{d_A^+}\Omega^2_+(\operatorname{ad}E)\). On the round \(S^4\), the Weitzenböck formula gives \(H_A^2=0\); irreducibility gives \(H_A^0=0\), so the index is the local moduli dimension. Such cokernel vanishing is not automatic on arbitrary four-manifolds.',r'This is the deformation argument underlying \citet{'+A+r'}; \citet[proof in \S3.2]{'+P+r'} explicitly use the same vanishing from positive scalar curvature and zero self-dual Weyl tensor.',[A,P],area='Gauge theory',cls='E',match='exact')
item(432,'P000732','theorem','Charge-one uniqueness and conformal symmetry',r'For \(n=1\), all solutions are said to be spherically symmetric up to gauge; the five-dimensional moduli space and conformal stabilizer are discussed.',r'Every charge-one \(SU(2)\) instanton on the round four-sphere is gauge-equivalent to a conformal transform of the basic instanton. Its unframed moduli are center and scale, giving a five-dimensional space. This is symmetry after choosing the corresponding conformal center and scale, not invariance under all rotations about an arbitrarily fixed point.',r'This is the charge-one case of the complete construction in \citet[\S4]{'+M+r'} and is consistent with the dimension theorem of \citet{'+A+r'}. The notebook\textquotesingle s group-dimension argument alone is not a proof of uniqueness.',[M,A],area='Gauge theory',cls='E',match='partial',verification='indirect',confidence='medium')
item(432,'P000731-P000732','question','Connectedness of fixed-charge instanton moduli',r'The notes ask whether the space of instanton solutions is connected, with charge two singled out as incompletely understood.',r'For each fixed positive charge \(k\), is the moduli space of \(SU(2)\) instantons on \(S^4\), modulo gauge, path-connected?',r'Taubes proved the \(SU(2)\) statement in 1984. \citet[Theorem~1.2 and \S3.3]{'+P+r'} give a new proof in 2026 and explicitly distinguish Taubes\textquotesingle s original rank restrictions from the general \(SU(r)\) extension. Thus the precise question is solved, not an open problem inherited from the notebook.',[P],area='Gauge theory',cls='B',literal='correct',problem='GP-1977-24',status='As of 10 November 2026, path-connectedness holds for every fixed-charge SU(2) instanton moduli space; the 2026 paper also states and proves the SU(r) version.')
item(432,'P000732','construction','A spectral-parameter formulation of self-duality',r'Two first-order covariant differential operators linear in \(\lambda\) are asserted to commute exactly when the duality equations hold; both displayed mixed terms have plus signs.',r'A consistent Euclidean pair, also recorded on P000741, is \(L_1=\lambda(\nabla_1-i\nabla_2)+(\nabla_3+i\nabla_4)\), \(L_2=\lambda(\nabla_3-i\nabla_4)-(\nabla_1+i\nabla_2)\). Vanishing of \([L_1,L_2]\) for every \(\lambda\) gives the three self-duality equations in the corresponding orientation. One cannot change the relative minus sign without changing the real structure or signature.',r'\citet[\S5 and references7--8]{'+M+r'} identify the Belavin--Zakharov construction used in the notes. The corrected explicit pair is checked by expanding the polynomial commutator, not read into the differently signed P000732 display.',[M],area='Gauge theory',cls='E',literal='false as written',match='partial',development='annotated',verification='indirect')
item(432,'P000732-P000733','construction','Orthogonal complex structures and the twistor fibration',r'All linear complex structures on \(\mathbb R^4\) are said to be parameterized by one complex parameter, and \(S^7\to\mathbb CP^3\to S^4\) is drawn.',r'The orientation-compatible orthogonal complex structures on a Euclidean four-space form \(SO(4)/U(2)\cong S^2\cong\mathbb CP^1\). All linear complex structures form a larger space. The twistor projection \(\mathbb CP^3\to\mathbb HP^1\cong S^4\) has fiber \(\mathbb CP^1\); it factors the quaternionic Hopf map through the circle quotient \(S^7\to\mathbb CP^3\).',r'The twistor construction is the setting of \citet{'+W+r'} and \citet[\S1]{'+M+r'}. The notebook omits orthogonality and prints an inconsistent \(\mathbb CP^2\) fiber near the bottom of P000733.',[W,M],area='Complex geometry and gauge theory',cls='E',literal='false as written',match='partial',verification='indirect')
item(432,'P000733','theorem','Instantons as holomorphic bundles on twistor space',r'The connection lifts to \(\mathbb CP^3\), defining an almost complex structure which is integrable precisely under the duality equations.',r'The pullback of a unitary anti-self-dual connection to twistor space defines an integrable \(\bar\partial\)-operator. For the inverse correspondence one requires a holomorphic bundle trivial on every real twistor line and a compatible real or quaternionic structure with positivity. An arbitrary holomorphic bundle on \(\mathbb CP^3\) does not determine a unitary instanton.',r'\citet[abstract]{'+W+r'} state the instanton/holomorphic-bundle identification; \citet[\S5]{'+M+r'} explicitly use this theorem in proving completeness. The full list of reality and line-triviality hypotheses is a modern reconstruction of the terse notes.',[W,M],area='Complex geometry and gauge theory',cls='E',literal='correct with missing hypotheses',match='partial',verification='indirect')
item(432,'P000733-P000734','claim','Integrability is involutivity of the complex tangent distribution',r'An almost complex structure is described by local vector fields, which are required to commute.',r'For a smooth almost complex structure \(J\), integrability is equivalent to involutivity \([T^{0,1},T^{0,1}]\subset T^{0,1}\), or vanishing Nijenhuis tensor. In holomorphic coordinates there is a commuting local frame, but an arbitrary frame of an integrable distribution need not commute. The base \(S^4\) is not thereby given a global complex structure.',r'The notebook is invoking the classical complex integrability criterion in its twistor application; \citet[\S5]{'+M+r'} rely on the resulting holomorphic-bundle correspondence. This reference is thematic for the general criterion, not a claimed original proof of it.',[M],area='Complex geometry',cls='E',literal='false as written',match='thematic only',verification='indirect',development='annotated')
prob('GP-1977-23','Finite-action Yang–Mills critical connections beyond instantons',r'Classify smooth finite-action SU(2) Yang--Mills connections on Euclidean four-space up to gauge, equivalently critical connections on bundles over the round four-sphere after removable-singularity compactification.',['1977-432.4'],r'As of 10 November 2026, ADHM-type data classify the self-dual or anti-self-dual minima, while nonminimal critical points also exist. The checked 2026 gap theorem controls an energy range and does not give a complete classification of all critical points.',[M,U,P])
prob('GP-1977-24','Fixed-charge instanton classification and connectedness',r'For each charge k, describe all SU(2) instantons on S4 up to gauge and determine whether their moduli space is path-connected.',['1977-432.8','1977-432.12'],r'The finite-dimensional construction was announced in 1977 and published in 1978; path-connectedness for SU(2) was proved by Taubes in 1984. Dayaprema--Waldron (2026), Theorem1.2 and section3.3, provide a new proof and explain the extension to SU(r).',[M,P])
